#!/bin/sh
# Prepare expat, whose expat_config.h is generated by cmake.
#
# expat parses XML for essentially everything: Python's ElementTree, Perl, PHP, Firefox,
# Chromium's older paths, and most C/C++ software that reads XML at all. It is also
# heavily fuzzed, which makes it a CALIBRATION target rather than a discovery one — if this
# engine cannot reach a decent fraction on expat, the number says something about the
# engine and not about the library.
set -eu
SRC="${1:-/b/expat}"
cat > "$SRC/expat/expat_config.h" <<'HDR'
#ifndef EXPAT_CONFIG_H
#define EXPAT_CONFIG_H
#define HAVE_MEMMOVE 1
#define HAVE_STDINT_H 1
#define HAVE_STDLIB_H 1
#define HAVE_STRING_H 1
#define HAVE_SYS_TYPES_H 1
#define HAVE_UNISTD_H 1
#define HAVE_GETRANDOM 1
#define STDC_HEADERS 1
#define XML_CONTEXT_BYTES 1024
#define XML_DTD 1
#define XML_GE 1
#define XML_NS 1
#define PACKAGE_VERSION "2.6.0"
/* Byte order: aarch64 and x86-64 are both little-endian. Stated, not detected — a wrong
   guess here changes how every multi-byte character is read. */
#define BYTEORDER 1234
#endif
HDR
echo "expat: wrote expat/expat_config.h"
